import{_ as e,o as r,c as d,ag as i}from"./chunks/framework.D7xI0JV8.js";const g=JSON.parse('{"title":"zkML + Circuit Stack","description":"","frontmatter":{},"headers":[],"relativePath":"zkml-circuits.md","filePath":"zkml-circuits.md"}'),o={name:"zkml-circuits.md"};function a(c,t,n,s,l,h){return r(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="zkml-circuit-stack" tabindex="-1">zkML + Circuit Stack <a class="header-anchor" href="#zkml-circuit-stack" aria-label="Permalink to &quot;zkML + Circuit Stack&quot;">​</a></h1><p>zkde.fi uses zero-knowledge machine learning to turn AI model outputs into verifiable, policy-aware signals. The system includes 31 Circom circuits, 2 EZKL ML models, and a bridge layer (ModelBridge) that converts arbitrary ONNX model outputs into on-chain-verifiable commitments via Garaga.</p><p>The result: AI outputs become evidence-bearing, policy-aware signals — not black-box recommendations.</p><h2 id="the-ezkl-pipeline" tabindex="-1">The EZKL Pipeline <a class="header-anchor" href="#the-ezkl-pipeline" aria-label="Permalink to &quot;The EZKL Pipeline&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20ONNX%5BONNX%20model%5D%20--%3E%20EZKL%5BEZKL%3A%20quantize%20%2B%20compile%5D%0A%20%20EZKL%20--%3E%20KZG%5BKZG%20commitment%20to%20model%20weights%5D%0A%20%20KZG%20--%3E%20INFER%5BPrivate%20inference%20on%20user%20data%5D%0A%20%20INFER%20--%3E%20G16%5BGroth16%20proof%20of%20correct%20inference%5D%0A%20%20G16%20--%3E%20BRIDGE%5BModelBridge%20circuit%5D%0A%20%20BRIDGE%20--%3E%20GAR%5BGaraga%20KZG%20pairing%20check%20in%20Cairo%5D%0A%20%20GAR%20--%3E%20CHAIN%5BOn-chain%20verified%20result%5D">flowchart LR
  ONNX[ONNX model] --&gt; EZKL[EZKL: quantize + compile]
  EZKL --&gt; KZG[KZG commitment to model weights]
  KZG --&gt; INFER[Private inference on user data]
  INFER --&gt; G16[Groth16 proof of correct inference]
  G16 --&gt; BRIDGE[ModelBridge circuit]
  BRIDGE --&gt; GAR[Garaga KZG pairing check in Cairo]
  GAR --&gt; CHAIN[On-chain verified result]</pre><ol><li><strong>Model training</strong> — a standard ML model is trained and exported as ONNX</li><li><strong>EZKL compilation</strong> — EZKL quantizes the model and compiles it into a Halo2 circuit with KZG commitments to the model weights</li><li><strong>KZG commitment</strong> — the model&#39;s weight commitment is registered on-chain, binding the model&#39;s identity</li><li><strong>Inference</strong> — the model runs on private user inputs; the user&#39;s data never leaves their control</li><li><strong>Groth16 proof</strong> — EZKL generates a proof that the model ran correctly on the given inputs and produced the given output</li><li><strong>ModelBridge</strong> — a Circom circuit that takes the EZKL proof output and bridges it into a format verifiable by Garaga&#39;s BN254 pairing check</li><li><strong>On-chain verification</strong> — Garaga verifies the Groth16 proof in Cairo on Starknet</li></ol><h2 id="ezkl-ml-models" tabindex="-1">EZKL ML Models <a class="header-anchor" href="#ezkl-ml-models" aria-label="Permalink to &quot;EZKL ML Models&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Architecture</th><th>Classes</th><th>Purpose</th></tr></thead><tbody><tr><td><code>yield_forecast</code></td><td>Linear(12→32)→ReLU→Linear(32→16)→ReLU→Linear(16→4)</td><td>declining / stable / growing / surging</td><td>Predict yield trajectory for pool allocation decisions</td></tr><tr><td><code>anomaly_detector</code></td><td>Linear(8→24)→ReLU→Linear(24→12)→ReLU→Linear(12→3)</td><td>safe / warning / critical</td><td>Detect anomalous pool behavior before capital enters</td></tr></tbody></table><p>Both models are compiled via EZKL into Halo2 circuits with KZG polynomial commitments. Proofs are verified on Ethereum Sepolia via the <a href="https://sepolia.etherscan.io/address/0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9" target="_blank" rel="noreferrer">Halo2Verifier</a> and bridged to Starknet via L1→L2 messaging or the ModelBridge circuit path.</p><h2 id="the-13-circuit-agent-screening-bundle" tabindex="-1">The 13-Circuit Agent Screening Bundle <a class="header-anchor" href="#the-13-circuit-agent-screening-bundle" aria-label="Permalink to &quot;The 13-Circuit Agent Screening Bundle&quot;">​</a></h2><p>Before any execution path is surfaced in Trade Desk, the relevant circuits from this bundle evaluate the action:</p><table tabindex="0"><thead><tr><th>#</th><th>Circuit</th><th>What It Proves</th></tr></thead><tbody><tr><td>1</td><td><code>RiskScore</code></td><td>Aggregate risk rating for a pool or position</td></tr><tr><td>2</td><td><code>AnomalyDetector</code></td><td>Whether pool behavior deviates from safe baselines</td></tr><tr><td>3</td><td><code>YieldOptimality</code></td><td>Whether the yield justifies the risk at current conditions</td></tr><tr><td>4</td><td><code>StrategyIntegrity</code></td><td>Whether the proposed strategy matches the committed parameters</td></tr><tr><td>5</td><td><code>ExecutionIntegrity</code></td><td>Whether the execution respected declared constraints (slippage, timing)</td></tr><tr><td>6</td><td><code>ImpermanentLossPredictor</code></td><td>Estimated IL exposure for LP positions</td></tr><tr><td>7</td><td><code>SlippageBound</code></td><td>Whether expected slippage stays within acceptable bounds</td></tr><tr><td>8</td><td><code>MEVResistanceProof</code></td><td>Whether the execution route has MEV protection characteristics</td></tr><tr><td>9</td><td><code>LiquidationRisk</code></td><td>Proximity to liquidation threshold for leveraged positions</td></tr><tr><td>10</td><td><code>CorrelationRisk</code></td><td>Cross-asset correlation risk in the portfolio context</td></tr><tr><td>11</td><td><code>CreditEligibility</code></td><td>Whether collateral posture meets lending thresholds</td></tr><tr><td>12</td><td><code>SolvencyProof</code></td><td>Verifiable solvency attestation</td></tr><tr><td>13</td><td><code>AgentReputationScore</code></td><td>Composite trust score from execution history</td></tr></tbody></table><p>Each circuit is compiled to WASM + zkey for fast client-side proof generation. The FICO-pack subset (Solvency, RiskPassportTier, TraderPerformance, StrategyIntegrity, ExecutionIntegrity) has dedicated on-chain verifier contracts:</p><table tabindex="0"><thead><tr><th>Verifier</th><th>Address</th></tr></thead><tbody><tr><td>SolvencyProofVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x043b253e3f2fcac35eef0b08fd2f8f4ff81aeb52848f11640d62879854329c9b" target="_blank" rel="noreferrer"><code>0x043b253e3f2fcac35eef0b08fd2f8f4ff81aeb52848f11640d62879854329c9b</code></a></td></tr><tr><td>RiskPassportTierVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x05e71cc0c4b87908230414644d675164fb90cd6d8cfafeae87198241e60eb788" target="_blank" rel="noreferrer"><code>0x05e71cc0c4b87908230414644d675164fb90cd6d8cfafeae87198241e60eb788</code></a></td></tr><tr><td>TraderPerformanceVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x04c8087855dd0812042de58b2a3f3838d3cea45118c86f07d32ac87648e90769" target="_blank" rel="noreferrer"><code>0x04c8087855dd0812042de58b2a3f3838d3cea45118c86f07d32ac87648e90769</code></a></td></tr><tr><td>StrategyIntegrityVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x00c9478f355bdad25caf13899a0d5bf2ee1accb1678e9934ebeda40f2653e549" target="_blank" rel="noreferrer"><code>0x00c9478f355bdad25caf13899a0d5bf2ee1accb1678e9934ebeda40f2653e549</code></a></td></tr><tr><td>ExecutionIntegrityVerifier</td><td><a href="https://sepolia.voyager.online/contract/0x03bb26a38ea2d8e4bd21895f665d0056a5496f31ad84f4d77e040d9e63e6873b" target="_blank" rel="noreferrer"><code>0x03bb26a38ea2d8e4bd21895f665d0056a5496f31ad84f4d77e040d9e63e6873b</code></a></td></tr></tbody></table><h2 id="additional-circom-circuits-full-31-circuit-set" tabindex="-1">Additional Circom Circuits (Full 31-Circuit Set) <a class="header-anchor" href="#additional-circom-circuits-full-31-circuit-set" aria-label="Permalink to &quot;Additional Circom Circuits (Full 31-Circuit Set)&quot;">​</a></h2><p>Beyond the 13 agent screening circuits, the system includes circuits for privacy, governance, and bridge operations:</p><table tabindex="0"><thead><tr><th>Category</th><th>Circuits</th></tr></thead><tbody><tr><td><strong>Privacy</strong></td><td>FullPrivacyWithdraw, FullPrivacyWithdrawHashed, FullPrivacyWithdrawWithChange, PrivateDeposit, PrivateWithdraw, PoolMembership</td></tr><tr><td><strong>Bridge</strong></td><td>ModelBridge, ModelBridgeHeavy</td></tr><tr><td><strong>Governance</strong></td><td>private_vote</td></tr><tr><td><strong>Position</strong></td><td>TWAPPosition, RebalanceTimingCommitment</td></tr><tr><td><strong>Attestation</strong></td><td>HistoricalPerformanceAttestation, RobustnessCertificate, SafetyDiversification</td></tr><tr><td><strong>Threshold</strong></td><td>BalanceAboveThreshold, TenureAboveThreshold</td></tr><tr><td><strong>DeFi</strong></td><td>CrossProtocolArbitrage, RiskPassportTier, TraderPerformanceProof</td></tr></tbody></table><p>Plus a <strong>Noir circuit</strong> (<code>noir_ezkl_bridge/</code>) for the Noir HONK proving lane.</p><h2 id="modelbridge-vs-modelbridgeheavy" tabindex="-1">ModelBridge vs ModelBridgeHeavy <a class="header-anchor" href="#modelbridge-vs-modelbridgeheavy" aria-label="Permalink to &quot;ModelBridge vs ModelBridgeHeavy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Artifact Size</th><th>Proving Time</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>ModelBridge</strong></td><td>Standard (~2MB zkey)</td><td>~3-5s</td><td>Default bridge for standard model outputs</td></tr><tr><td><strong>ModelBridgeHeavy</strong></td><td>Heavy (~8MB zkey)</td><td>~10-15s</td><td>Complex model outputs requiring more constraint capacity</td></tr></tbody></table><p>Both variants produce Groth16 proofs verified by the same Garaga verifier infrastructure on Starknet.</p><h2 id="modelbridge-verifier-contract" tabindex="-1">ModelBridge Verifier Contract <a class="header-anchor" href="#modelbridge-verifier-contract" aria-label="Permalink to &quot;ModelBridge Verifier Contract&quot;">​</a></h2><p>The on-chain entry point for verifying bridged EZKL proofs:</p><p><a href="https://sepolia.voyager.online/contract/0x037c42e8734271aca0c3c1bdf1746d9ccc098ddfd5ee211c94bbb8786fa4626f" target="_blank" rel="noreferrer"><code>0x037c42e8734271aca0c3c1bdf1746d9ccc098ddfd5ee211c94bbb8786fa4626f</code></a> (Starknet Sepolia)</p><h2 id="zkml-api-endpoints" tabindex="-1">zkML API Endpoints <a class="header-anchor" href="#zkml-api-endpoints" aria-label="Permalink to &quot;zkML API Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/risk_score</code></td><td>Risk score proof/signal generation</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/anomaly</code></td><td>Anomaly detection signal</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/combined</code></td><td>Combined risk + anomaly path</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/status</code></td><td>zkML subsystem status</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/pool-safety</code></td><td>Pool safety snapshot</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/scan</code></td><td>Scan-oriented model path</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/circuits</code></td><td>Circuit metadata</td></tr></tbody></table><hr><p>Next: <a href="/docs/proof-pipeline">Proof Pipeline</a> | <a href="/docs/privacy-rails">Privacy Rails</a> | <a href="/docs/api-overview">API Overview</a></p>`,28)])])}const p=e(o,[["render",a]]);export{g as __pageData,p as default};
